import { useState } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { login } from '../api';

export default function Login() {
  const [form, setForm] = useState({ contact: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const message = location.state?.message;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const response = await login(form);
      const { user } = response.data;
      localStorage.setItem('trip-planner-user', JSON.stringify(user));
      navigate('/planner');
    } catch (err) {
      setError(err.response?.data?.error || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} className="max-w-xl mx-auto mt-16 bg-slate-800 rounded-xl shadow-lg p-8">
      <h1 className="text-2xl font-bold mb-4">Login to Smart Budget Trip Planner</h1>
      {message && <p className="text-lime-300 mb-3">{message}</p>}
      <form onSubmit={handleSubmit} className="space-y-4">
        <input name="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="Email" className="w-full p-3 rounded-lg bg-slate-700" required />
        <input type="password" name="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="Password" className="w-full p-3 rounded-lg bg-slate-700" required />
        {error && <p className="text-red-400">{error}</p>}
        <button type="submit" disabled={loading} className="w-full py-3 bg-blue-600 hover:bg-blue-500 rounded-lg font-semibold transition">
          {loading ? 'Logging in...' : 'Login'}
        </button>
      </form>
      <p className="mt-4 text-sm text-slate-300">New? <Link to="/signup" className="text-cyan-300">Signup</Link></p>
    </motion.div>
  );
}
